import * as THREE from 'three/webgpu';
import { texture, uv, uniform, mix, vec3, vec4, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-quote-panel';
  group.position.set(2.5, 0.7000000000000001, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const hoverAmount = uniform(0);
  const accentColor = vec3(1.0, 0.1647, 0.2196);
  const surfaceColor = vec3(0.0431, 0.0431, 0.0627);

  const material = new THREE.MeshBasicNodeMaterial();
  material.transparent = true;

  const texSample = texture(map, uv());
  const tintMix = mix(texSample.rgb, mix(surfaceColor, accentColor, hoverAmount.mul(0.3)), 0.05);
  material.colorNode = vec4(tintMix, texSample.a);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'quote-panel-mesh';
  group.add(mesh);

  // Accent edge frame (thin border plane) for focus indication
  const edgeGeometry = new THREE.PlaneGeometry(width + 0.03, height + 0.03);
  const edgeMaterial = new THREE.MeshBasicNodeMaterial();
  edgeMaterial.transparent = true;
  const edgeOpacity = uniform(0);
  edgeMaterial.colorNode = vec4(accentColor, edgeOpacity);
  const edgeMesh = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.z = -0.001;
  edgeMesh.visible = false;
  group.add(edgeMesh);

  // Apply cinematic primitives from config
  const primitivesToApply = config.cinematicPrimitives || [];
  primitivesToApply.forEach((primitive) => {
    if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  });

  const baseY = group.position.y;
  let hoverTween = null;
  let pressTween = null;

  function onHoverIn() {
    edgeMesh.visible = true;
    hoverTween && hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0)
      .to(hoverAmount, { value: 1, duration: 0.7, ease: 'power3.out' }, 0)
      .to(edgeOpacity, { value: 0.9, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onHoverOut() {
    hoverTween && hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0)
      .to(hoverAmount, { value: 0, duration: 0.5, ease: 'power2.out' }, 0)
      .to(edgeOpacity, { value: 0, duration: 0.3, ease: 'power2.out', onComplete: () => { edgeMesh.visible = false; } }, 0);
  }

  function onClick() {
    pressTween && pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out' });

    if (ctx.emit) {
      ctx.emit('hub-journal.select', { nodeId: 'hub-journal-quote-panel' });
    }
  }

  group.userData.handlers = {
    onHoverIn,
    onHoverOut,
    onClick,
  };

  group.userData.cleanup = function cleanup() {
    hoverTween && hoverTween.kill();
    pressTween && pressTween.kill();
    geometry.dispose();
    edgeGeometry.dispose();
    material.dispose();
    edgeMaterial.dispose();
    if (map) map.dispose();
  };

  return group;
}
